};

@Injectable()
export class CoursesService {
  private readonly courses:
    Course[] = [
      {
        id: 1,
        title: 'TypeScript',
      },
      {
        id: 2,
        title: 'NestJS',
      },
    ];

  getCourses(): Course[] {
    return this.courses;
